solution.code:
function buatKeranjang() {
  const item = [];
  return {
    tambah(nama, harga, jumlah = 1) {
      if (!Number.isInteger(jumlah) || jumlah <= 0) {
        throw new Error("Jumlah harus bilangan bulat positif");
      }
      const ada = item.find((i) => i.nama === nama);
      if (ada) ada.jumlah += jumlah;
      else item.push({ nama, harga, jumlah });
    },
    hapus(nama) {
      const idx = item.findIndex((i) => i.nama === nama);
      if (idx === -1) return false;
      item.splice(idx, 1);
      return true;
    },
    jumlahItem() {
      return item.reduce((n, i) => n + i.jumlah, 0);
    },
    subtotal() {
      return item.reduce((n, i) => n + i.harga * i.jumlah, 0);
    },
    total(kupon) {
      const sub = this.subtotal();
      if (kupon === "HEMAT10" && sub >= 100000) return Math.round(sub * 0.9);
      return sub;
    },
  };
}

